// Entrada desde W1 (o desde el webhook de prueba, mismo shape).
const j0 = $input.first().json || {};
const porWebhook = !!(j0.body && j0.body.sessionId !== undefined);
const src = porWebhook ? j0.body : j0;
for (const k of ['sessionId', 'contactId']) {
  if (!src[k]) throw new Error(`W7: falta "${k}"`);
}
let adj = src.adjuntos ?? [];
if (typeof adj === 'string') {
  const t = adj.trim();
  try { adj = t.startsWith('[') ? JSON.parse(t) : (t ? [t] : []); }
  catch (e) { adj = t ? [t] : []; }
}
if (!Array.isArray(adj)) adj = adj ? [adj] : [];
if (!adj.length) throw new Error('W7: llegó sin adjuntos — este carril es sólo para media');

return [{ json: {
  _via: porWebhook ? 'webhook' : 'subworkflow',
  sessionId: String(src.sessionId),
  contactId: String(src.contactId),
  opportunityId: src.opportunityId ?? null,
  texto: String(src.texto ?? ''),
  tipo: src.tipo || 'imagen',
  adjuntos: adj,
  url: String(adj[0]),
  etapa: src.etapa ?? null,
  _forzar_fuera_horario: src._forzar_fuera_horario ?? false,
  fecha: $now.setZone('America/Mexico_City').toFormat("cccc dd/LL/yyyy HH:mm"),
} }];

function textoDelModelo(j) {
  if (j == null) return '';
  if (typeof j === 'string') return j;
  if (typeof j.content === 'string') return j.content;
  if (Array.isArray(j.content)) {
    return j.content.map(c => (typeof c === 'string' ? c : (c && c.text) || '')).join(' ');
  }
  if (j['0']) return textoDelModelo(j['0']);
  if (j.message && j.message.content) return textoDelModelo(j.message);
  return '';
}

const ctx = $('Normalizar entrada').first().json;
const t = textoDelModelo($input.first().json).trim().toLowerCase();
// El prompt congelado devuelve literalmente true / false.
const esPago = t.includes('true') && !t.includes('false');
return [{ json: { ...ctx, es_pago: esPago, _analisis_pago: t.slice(0, 120) } }];

// Imagen que no es comprobante, de un lead que ya está en producción. El origen sólo
// avisa por Telegram y NO le responde nada al lead: la conversación la maneja una
// persona. Se replica el silencio a propósito.
const ctx = $('Leer comprobante').first().json;
return [{ json: { ok: true, modo: 'partes',
  sessionId: ctx.sessionId, contactId: ctx.contactId,
  step: 'media_en_produccion', tools_usadas: [], etapa_destino: null,
  partes: [],
  _alerta: `📸 El lead ${ctx.contactId} envió una *IMAGEN* y está en *EN PRODUCCIÓN*.` } }];

function textoDelModelo(j) {
  if (j == null) return '';
  if (typeof j === 'string') return j;
  if (typeof j.content === 'string') return j.content;
  if (Array.isArray(j.content)) {
    return j.content.map(c => (typeof c === 'string' ? c : (c && c.text) || '')).join(' ');
  }
  if (j['0']) return textoDelModelo(j['0']);
  if (j.message && j.message.content) return textoDelModelo(j.message);
  return '';
}

const ctx = $('Normalizar entrada').first().json;
const t = textoDelModelo($input.first().json).trim();
// Réplica de `Es producto?` del origen: content notContains 'falso'.
const esProducto = !!t && !t.toLowerCase().includes('falso');
return [{ json: { ...ctx, contenido: t, es_producto: esProducto } }];

// Corta la respuesta del Recolector1 en burbujas. Mismo criterio que W6: párrafos,
// máximo 3, y una cotización o el bloque de los 7 pasos nunca se parten.
const ctx = $('Leer producto').first().json;
const salida = $input.first().json;
let txt = String(salida.output ?? salida.text ?? '').trim();
if (!txt) throw new Error('W7: Recolector1 no devolvió texto');

const PAR = [['"', '"'], ['“', '”'], ["'", "'"], ['«', '»']];
for (const [a, b] of PAR) {
  if (txt.length > 1 && txt.startsWith(a) && txt.endsWith(b)) {
    txt = txt.slice(a.length, -b.length).trim(); break;
  }
}
const INDIVISIBLE = /(Cotizaci[óo]n|Anticipo|7 SENCILLOS PASOS|7 DIAS DE PROMO)/i;
let partes;
if (INDIVISIBLE.test(txt)) partes = [txt];
else {
  partes = txt.split(/\n\s*\n/).map(s => s.trim()).filter(Boolean);
  if (partes.length > 3) partes = [partes[0], partes[1], partes.slice(2).join('\n\n')];
  if (!partes.length) partes = [txt];
}
const pasos = (salida.intermediateSteps || []).map(s => s?.action?.tool).filter(Boolean);
return [{ json: { ok: true, modo: 'partes',
  sessionId: ctx.sessionId, contactId: ctx.contactId,
  step: 'media_producto', tools_usadas: pasos,
  // Una foto de producto no mueve el embudo: el lead todavía no pidió nada.
  etapa_destino: null,
  partes: partes.map(p => ({ texto: p, adjuntos: [] })),
  _alerta: `📷✔️ El lead ${ctx.contactId} envió una *imagen CATEGORIZABLE* (${ctx.contenido.slice(0, 60)}).` } }];

// Imagen que el clasificador no pudo encasillar: el origen avisa y deriva a una
// persona (ATENCION_PERSONALIZADA4). W5 ya hace la derivación completa.
const ctx = $('Leer producto').first().json;
const r = $input.first().json || {};
return [{ json: { ok: true, modo: 'partes',
  sessionId: ctx.sessionId, contactId: ctx.contactId,
  step: 'media_no_categorizable', tools_usadas: ['ATENCION_PERSONALIZADA'],
  etapa_destino: null,
  partes: [{ texto: r.message_to_user || r.mensaje ||
    'Ya avisé al equipo para que una persona te ayude con esa imagen.', adjuntos: [] }],
  _alerta: `📷❌ El lead ${ctx.contactId} envió una *imagen NO CATEGORIZABLE*.` } }];

const ctx = $('Normalizar entrada').first().json;
const enProduccion = ctx.etapa === 'En Producción';

// El segundo pago (liquidación) NO tiene etapa equivalente en GHL: el pipeline tiene
// 13 y ninguna es "pago liquidación" (Kommo 100395523). En vez de inventar una etapa
// —que sería un cambio destructivo sobre el pipeline del cliente— se deja el lead
// donde está y se registra en los campos custom que YA existen para eso.
const campos = enProduccion
  ? { comprobante_liquidacion_url: ctx.url, comprobante_liquidacion_at: ctx.fecha }
  : { comprobante_anticipo_url: ctx.url, comprobante_anticipo_at: ctx.fecha,
      payment_proof_detectado: true };

return [{ json: {
  ...ctx,
  tipo_pago: enProduccion ? 'liquidacion' : 'anticipo',
  campos,
  mover_etapa: !enProduccion,
  etapa_destino: enProduccion ? null : 'Pago Confirmado',
  _alerta: enProduccion
    ? `💰 El lead ${ctx.contactId} envió un *comprobante de LIQUIDACIÓN* (está en producción). Verificar que llegó.`
    : `💰 El lead ${ctx.contactId} envió una *captura de un pago*. Por favor comprobar que les llegó.`,
} }];

const TZ = 'America/Mexico_City';
const p = new Intl.DateTimeFormat('en-US', {
  timeZone: TZ, weekday: 'short', hour: 'numeric', minute: 'numeric', hour12: false,
}).formatToParts(new Date()).reduce((a, x) => (a[x.type] = x.value, a), {});

const dia = p.weekday;
const min = parseInt(p.hour, 10) * 60 + parseInt(p.minute, 10);
const HABILES = new Set(['Mon', 'Tue', 'Wed', 'Thu', 'Fri']);
let enHorario = false;
if (HABILES.has(dia)) enHorario = min >= 540 && min < 1080;        // 09:00–18:00
else if (dia === 'Sat') enHorario = min >= 540 && min < 840;       // 09:00–14:00

const ctx = $('Decidir pago').first().json;

// Seam de test. La rama de fuera de horario manda un asset DISTINTO (la foto de
// vacaciones), así que si no se puede forzar sólo se la puede probar de noche o en
// domingo — o sea, nunca. `_forzar_fuera_horario` llega en el payload del turno y no
// hay forma de que lo mande GHL: el contrato de W1 no lo propaga desde el webhook
// real, sólo desde el carril de prueba.
const forzado = ctx._forzar_fuera_horario === true || ctx._forzar_fuera_horario === 'true';
if (forzado) enHorario = false;

return [{ json: { ...ctx, en_horario: enHorario,
                  _horario: { dia, min, forzado } } }];

const ctx = $('Guardia de horario').first().json;
return [{ json: { ok: true, modo: 'partes',
  sessionId: ctx.sessionId, contactId: ctx.contactId,
  step: 'media_pago', tools_usadas: ['PAGO'],
  etapa_destino: ctx.etapa_destino,
  partes: [{ texto: "Muchas gracias por tu pago, lo estaremos verificando a la brevedad", adjuntos: [] }],
  _alerta: ctx._alerta } }];

const ctx = $('Guardia de horario').first().json;
// Fuera de horario el origen manda el salesbot 60860, que es la "Foto Vacaciones":
// una imagen, no un texto. El asset ya está migrado al catálogo.
return [{ json: { ok: true, modo: 'partes',
  sessionId: ctx.sessionId, contactId: ctx.contactId,
  step: 'media_pago_fuera_horario', tools_usadas: ['PAGO'],
  etapa_destino: ctx.etapa_destino,
  partes: [{ texto: '', adjuntos: ["https://assets.cdn.filesafe.space/onRwi0ZF4uYi0Lp6GAbE/media/361760b5-c8ec-4a79-bc9d-ebb02f9aa624.jpeg"] }],
  _alerta: ctx._alerta + ' (llegó FUERA de horario)' } }];

// Devuelve al llamador el payload del productor que efectivamente corrió.
//
// No se puede leer `$json`: el nodo de Telegram está en el medio del camino y su
// salida es el acuse de la API, no la respuesta al lead. Es la misma trampa que ya
// documentamos en W6 con el gate de cotización.
const CANDIDATOS = ['Respuesta pago', 'Respuesta fuera de horario',
                    'Imagen en producción', 'Partir en burbujas', 'Derivación a partes'];
for (const nombre of CANDIDATOS) {
  const n = $(nombre);
  if (n.isExecuted) return [{ json: n.first().json }];
}
throw new Error('W7: ninguna rama produjo salida — revisar el ruteo por tipo');

